// en-est — generated from src/en-est-*.js by tools/merge.js. Edit the src files, then run: node tools/merge.js
// Construction Estimator. Format: [topic, question, answer, 'B'|'D', 'E'|'M'|'S'|'X', source, { t: top, f: [follow-up q, a] }]
QB["en-est"] = (QB["en-est"] || []).concat([
["Fundamentals", "What does a construction estimator do?", "**Why they ask:** the opening question.\n\n**Answer:**\n\"I determine what a construction project will cost — taking off quantities from drawings, pricing materials, labor, equipment and subcontractors, adding overhead, contingency and profit, and producing a bid or budget. A good estimate wins work at a margin the company can actually deliver; too high loses the bid, too low wins a money-losing job. So accuracy and sound judgment on risk directly drive the company's profitability.\"\n\nTip: Win profitable work — too high loses, too low loses money.", "B", "M", null, {"t":1,"f":["What's the cost of a bad estimate?","Too high and you lose the bid; too low and you win a job that loses money — both hurt the business."]}],
["Takeoff", "What is a quantity takeoff and how do you do it?", "**Why they ask:** the core daily task.\n\n**Answer:**\n\"It's measuring and counting all the materials and work from the drawings and specs — square footage, linear feet, counts, volumes — systematically so nothing is missed or double-counted. I work trade by trade, use takeoff software, and cross-check against the specs. Thoroughness is everything: a missed quantity is a cost you eat later. I follow a consistent method so the takeoff is complete and auditable.\"\n\nTip: Systematic, complete, no double-counting; a miss becomes a loss.", "D", "M", null, {"t":1,"f":["What happens if you miss a scope item?","It's not in the bid, so the company absorbs that cost or has to claim a change order — a margin hit."]}],
["Pricing", "How do you price labor for an estimate?", "**Why they ask:** labor is the biggest risk.\n\n**Answer:**\n\"I estimate the labor hours for each task using production rates (units per crew-hour) from historical data or references, apply the crew mix and wage rates including burden (taxes, benefits, insurance), and factor conditions — access, weather, overtime, complexity. Labor is the least predictable cost and the biggest risk, so realistic productivity assumptions matter more than material prices, which are more fixed.\"\n\nTip: Hours × crew rate (with burden); productivity is the big risk.", "D", "M", null, {"t":1,"f":["Why is labor riskier than materials?","Material prices are quoted and fairly fixed; labor productivity varies hugely with conditions, crew and management."]}],
["Subs", "How do you handle subcontractor pricing?", "**Why they ask:** most work is subbed out.\n\n**Answer:**\n\"I solicit bids from qualified subs, make sure their scope matches the full requirement with no gaps or overlaps between trades, compare apples to apples, and account for their reliability, not just price. Scope gaps between subs — where each assumes the other is doing something — are a classic source of cost overruns, so I level the bids carefully to ensure complete coverage.\"\n\nTip: Level bids to the same scope; watch for gaps between trades.", "D", "M", null, {"f":["What's bid leveling?","Normalizing subcontractor bids to the same scope so you compare equivalent prices and catch exclusions or gaps."]}],
["Contingency", "How do you handle contingency and risk in an estimate?", "**Why they ask:** risk judgment.\n\n**Answer:**\n\"I add contingency based on the project's uncertainty — design completeness, site unknowns, schedule risk, market volatility. An early-stage estimate with incomplete drawings needs more contingency than a fully detailed one. I identify specific risks and either price them or flag assumptions and exclusions clearly. Contingency covers the known-unknowns; clear exclusions protect against scope that isn't ours.\"\n\nTip: Contingency scaled to uncertainty; state assumptions and exclusions.", "D", "M", null, {"f":["Why state exclusions clearly?","So the bid can't be assumed to include scope it doesn't — avoiding disputes and unpriced work later."]}],
["Types", "What's the difference between a rough and a detailed estimate?", "**Why they ask:** estimate stages.\n\n**Answer:**\n\"Early conceptual estimates use rough methods — cost per square foot or parametric models — when design is incomplete, with wide accuracy ranges. Detailed estimates come from full takeoffs and current pricing on complete documents, much tighter. I match the method and stated accuracy to the design stage and make sure stakeholders understand the confidence level, so no one treats a conceptual number as a firm bid.\"\n\nTip: Match method and stated accuracy to the design stage.", "D", "M", null, {"f":["What's a parametric estimate?","Cost derived from key parameters (like $/SF or $/bed) based on historical data, used early when details are unknown."]}],
["Value engineering", "What is value engineering in estimating?", "**Why they ask:** cost optimization.\n\n**Answer:**\n\"It's finding ways to deliver the required function at lower cost — alternative materials, methods or designs — without sacrificing quality or performance. When a bid comes in over budget, I work with the team to identify VE options and their cost and schedule impact, so the owner can make informed trade-offs. It's about value, not just cutting — the cheapest option that fails the requirement isn't a saving.\"\n\nTip: Same function, lower cost — value, not just cheaper.", "D", "M", null, {"f":["When does VE typically happen?","When a bid exceeds budget, to find savings before awarding — or in design to control cost early."]}],
["Software", "What estimating tools and skills do you use?", "**Why they ask:** practical fit.\n\n**Answer:**\n\"Estimating and takeoff software like Bluebeam, PlanSwift, or systems like Timberline/Sage, cost databases like RSMeans, and strong spreadsheet skills. I also read drawings and specs fluently and keep a historical cost database from past projects, which is often the most valuable pricing source because it reflects how our company actually performs.\"\n\nTip: Historical company data is the best pricing source.", "B", "M", null, {"f":["Why is historical data so valuable?","It reflects your company's real productivity and costs, which are more accurate than generic published rates."]}],
["Behavioral", "Tell me about an estimate where accuracy mattered.", "**Why they ask:** real experience.\n\n**Answer (example):**\n\"On a competitive bid, I did a thorough takeoff and caught a significant scope item others' quick estimates missed, and leveled the sub bids carefully to close gaps. We won at a realistic margin and delivered without eating surprise costs, while a lower bidder would have lost money on the missed scope. Diligence protected the margin.\"\n\nTip: Show thoroughness protecting margin on a real bid.", "D", "M", null, {"t":1,"f":["How do you avoid missing scope?","A systematic trade-by-trade checklist against drawings and specs, and cross-checking sub scopes for gaps."]}],
["Collaboration", "How do you work with the project team after you win a bid?", "**Why they ask:** estimate-to-execution handoff.\n\n**Answer:**\n\"I hand off a clear budget breakdown to the project manager and team, explain the assumptions, allowances and risks I built in, and support buyout. I also capture actual costs versus my estimate afterward to improve future estimating. A good handoff and the feedback loop between estimated and actual costs make the next estimate better.\"\n\nTip: Clear handoff plus an estimate-vs-actual feedback loop.", "B", "M", null, {"f":["Why track estimated vs actual costs?","It reveals where your assumptions were off so you calibrate future estimates — continuous improvement."]}],
["Judgment", "A bid is due tomorrow and you're missing key pricing. What do you do?", "**Why they ask:** real pressure.\n\n**Answer:**\n\"I'd prioritize the biggest cost items, chase the critical quotes, use historical data or conservative allowances for gaps, and clearly flag assumptions and exclusions so the risk is visible to leadership for the bid decision. I'd rather state a defensible assumption than guess silently. The go/no-go on the bid should be made with the risks known.\"\n\nTip: Prioritize big items, use historical allowances, flag assumptions.", "D", "M", null, {"f":["Why flag assumptions rather than hide them?","So leadership prices the risk knowingly and the bid isn't exposed to unpriced scope."]}],
["Closing", "Why construction estimating?", "**Why they ask:** motivation.\n\n**Answer:**\n\"I like the mix of analytical rigor, construction knowledge and direct business impact — a good estimate wins work and protects margin, and I enjoy the detail and the puzzle of pricing a project right. It's where the numbers meet the build.\"\n\nTip: Analytical, detail-driven, directly tied to winning profitable work.", "B", "M", null, {"f":["What type of construction interests you?","Tailor it — commercial, industrial, residential, infrastructure — and why it fits your experience."]}]
]);

